import{_ as t,o,c as s,ag as a}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/settings-default-home.png",i="/nada-documentation/images/customizing-home-page-menu-pages-list.png",m=JSON.parse('{"title":"Customizing the home page","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/customizing-home-page.md","filePath":"admin-guide/web-ui/customizing-home-page.md","lastUpdated":1786379412000}'),r={name:"admin-guide/web-ui/customizing-home-page.md"};function d(c,e,h,l,p,g){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="customizing-the-home-page" tabindex="-1">Customizing the home page <a class="header-anchor" href="#customizing-the-home-page" aria-label="Permalink to &quot;Customizing the home page&quot;">​</a></h1><p>The <strong>home page</strong> is what visitors see when they open your NADA site root URL (no path after the domain). NADA resolves that request in <code>Page</code> (default front controller): it uses your <strong>default home page</strong> setting, then menu definitions, and optionally <strong>static PHP views</strong>. You can customize the experience in two main ways—through <strong>Site administration</strong> (menus and settings), or by placing files under <strong><code>application/views/static/custom/</code></strong> for advanced control.</p><div class="tip custom-block"><p class="custom-block-title">Relationship to other settings</p><p>The <strong>Website title</strong> and <strong>Website footer</strong> text are set under <a href="/nada-documentation/admin-guide/web-ui/site-configurations.html">Site configurations</a>. Top navigation and custom pages are managed under <a href="/nada-documentation/admin-guide/web-ui/site-menus.html">Site menus</a>. For the <strong>site header, footer, and styling</strong> (including <strong><code>themes/nada52/css/custom.css</code></strong>), see <a href="/nada-documentation/installation-guide/configurations/customizing-themes.html">Customizing themes</a>.</p></div><h2 id="_1-using-site-administration-menus-and-settings" tabindex="-1">1. Using Site administration (menus and settings) <a class="header-anchor" href="#_1-using-site-administration-menus-and-settings" aria-label="Permalink to &quot;1. Using Site administration (menus and settings)&quot;">​</a></h2><p>This path suits most catalogs: HTML content or a redirect, without touching server files.</p><h3 id="set-the-default-home-page" tabindex="-1">Set the default home page <a class="header-anchor" href="#set-the-default-home-page" aria-label="Permalink to &quot;Set the default home page&quot;">​</a></h3><p>In <strong>Site administration</strong>, open <strong>Settings</strong> → <strong>Site configurations</strong> → <strong>General site settings</strong>. Use <strong>Default home page</strong> to set which <strong>slug</strong> loads when someone visits the site root.</p><p>Enter the <strong>first segment of the URL path</strong> NADA should use—for example <code>catalog</code>, <code>home</code>, or <code>about</code>—matching a <strong>menu entry</strong> or a static page name (see below).</p><p><img src="'+n+'" alt=""></p><h3 id="build-content-with-menus" tabindex="-1">Build content with menus <a class="header-anchor" href="#build-content-with-menus" aria-label="Permalink to &quot;Build content with menus&quot;">​</a></h3><p>Under <strong>Site administration</strong>, use <strong>Menu → All pages</strong> (and related menu tools) to:</p><ul><li>Create <strong>HTML pages</strong> stored in the database and linked from the main menu.</li><li>Add <strong>links</strong> that send users to another route (for example, open <strong>Catalog</strong> directly from the menu or as the configured default).</li></ul><p>When <strong>Default home page</strong> points at a <strong>menu HTML page</strong>, NADA renders that page’s body at <code>/</code>. When it points at a <strong>link</strong> entry, visitors are <strong>redirected</strong> to the linked URL (for example <code>/catalog</code>).</p><div class="warning custom-block"><p class="custom-block-title">Match the slug</p><p>The value in <strong>Default home page</strong> must match the <strong>URL / slug</strong> of the menu page or link you created—not necessarily the visible menu label.</p></div><p><img src="'+i+'" alt=""></p><p>If <strong>Default home page</strong> is left unset, NADA falls back to other rules (such as the lowest-weight menu item). Configure <strong>Default home page</strong> explicitly to avoid surprises.</p><hr><h2 id="_2-using-views-static-custom-advanced" tabindex="-1">2. Using <code>views/static/custom</code> (advanced) <a class="header-anchor" href="#_2-using-views-static-custom-advanced" aria-label="Permalink to &quot;2. Using `views/static/custom` (advanced)&quot;">​</a></h2><p>For layouts that need <strong>PHP</strong>, shared partials, or logic beyond the admin HTML editor, use static views on the server.</p><h3 id="how-static-pages-resolve" tabindex="-1">How static pages resolve <a class="header-anchor" href="#how-static-pages-resolve" aria-label="Permalink to &quot;How static pages resolve&quot;">​</a></h3><p>NADA looks for views in this order:</p><ol><li><strong><code>application/views/static/custom/{slug}.php</code></strong> — your overrides (keep these when upgrading).</li><li><strong><code>application/views/static/{slug}.php</code></strong> — pages shipped with NADA.</li></ol><p>The <code>{slug}</code> is the same path segment you use in <strong>Default home page</strong> (for example <code>home</code>).</p><h3 id="shipped-default-home-page" tabindex="-1">Shipped default home page <a class="header-anchor" href="#shipped-default-home-page" aria-label="Permalink to &quot;Shipped default home page&quot;">​</a></h3><p>NADA includes a default <strong>home</strong> view at:</p><p><code>application/views/static/home.php</code></p><p>That file drives the stock landing experience (for example search area, statistics, and lists of popular or recent studies). It is a normal PHP view; you may rely on models and helpers already loaded by the controller.</p><p><strong>To customize safely across upgrades</strong>, copy the file into the custom folder and edit the copy:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>application/views/static/home.php</span></span>\n<span class="line"><span>        → application/views/static/custom/home.php</span></span></code></pre></div><p>Then set <strong>Default home page</strong> to <code>home</code> if it is not already. Only files under <strong><code>custom/</code></strong> should be edited for long-term maintenance; treat files under <code>views/static/</code> (without <code>custom</code>) as read-only vendor defaults.</p><h3 id="optional-custom-home-template-home-custom-php" tabindex="-1">Optional custom home template (<code>home.custom.php</code>) <a class="header-anchor" href="#optional-custom-home-template-home-custom-php" aria-label="Permalink to &quot;Optional custom home template (`home.custom.php`)&quot;">​</a></h3><p>NADA may ship an alternate starter layout at:</p><p><code>application/views/static/custom/home.custom.php</code></p><p>That filename is <strong>not</strong> loaded automatically as the home page—only <strong><code>home.php</code></strong> is used for the <code>home</code> slug. To adopt this template, <strong>copy</strong> <code>home.custom.php</code> to <strong><code>home.php</code></strong> in the same folder, or <strong>rename</strong> <code>home.custom.php</code> to <strong><code>home.php</code></strong>. Then edit <code>home.php</code> as needed.</p><p>Choose one approach:</p><ul><li><strong>Copy</strong> — Keeps <code>home.custom.php</code> on disk as a reference or starting point for future merges after upgrades.</li><li><strong>Rename</strong> — Activates the template immediately; keep a backup elsewhere if you still want the original <code>.custom</code> file for comparison.</li></ul><p>Ensure <strong>Default home page</strong> is set to <strong><code>home</code></strong> so the site root uses this view.</p><h3 id="other-static-slugs" tabindex="-1">Other static slugs <a class="header-anchor" href="#other-static-slugs" aria-label="Permalink to &quot;Other static slugs&quot;">​</a></h3><p>You can add more files, for example <code>application/views/static/custom/about.php</code>, and expose them via the menu or <strong>Default home page</strong> using the matching slug (<code>about</code>).</p><div class="danger custom-block"><p class="custom-block-title">Server access required</p><p>Deploying files under <code>application/views/static/custom/</code> requires access to the web server or your deployment pipeline. Incorrect PHP can cause errors on the affected page—test after each change.</p></div><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Approach</th><th>Best for</th><th>Where</th></tr></thead><tbody><tr><td>Menus + <strong>Default home page</strong></td><td>Editorial HTML, redirects, no server access</td><td>Site administration</td></tr><tr><td><strong><code>views/static/custom/{slug}.php</code></strong></td><td>PHP layouts, reuse of NADA helpers/models, full control</td><td>Server filesystem</td></tr></tbody></table>',43)])])}const f=t(r,[["render",d]]);export{m as __pageData,f as default};
